import './photo-instance-import.mjs';
const by=id=>document.getElementById(id),endpoint='http://127.0.0.1:8191',api=()=>globalThis.coexLayerLayout;
const panel=document.createElement('details');panel.id='occlusionRepairPanel';panel.innerHTML='<summary>가려진 물체 부분 보완</summary><p class="layer-help">분리된 물체를 선택해 보완 영역을 확인하세요. 빨간 영역과 맞닿은 좁은 투명 틈을 보완하며, 기본 후보는 원래 보이는 픽셀을 보존합니다. 경계 자연 연결을 켜면 접합부 주변 최대 96px의 색·질감도 보정합니다. 적용 전 미리보기로 비교하고 복원할 수 있습니다. 생성 부분은 추정이며 원본 복원이 아닙니다. 로컬 모델의 결과가 부정확하거나 준비되지 않으면 적용하지 않고 원본을 유지합니다.</p><label>생성 방식 <select id="repairProvider"><option value="powerpaint">PowerPaint · 무료 로컬</option><option value="local">기존 로컬 모델 · 시험</option><option value="openai">OpenAI 이미지 편집 API · 유료</option></select></label><label id="repairFreshLabel"><input type="checkbox" id="repairFresh">저장된 후보 대신 새로 생성 · 수 분 소요</label><label id="repairJoinLabel"><input type="checkbox" id="repairJoin">표면 결·질감 자연 연결 · 끄면 원본 픽셀 보존</label><p id="repairProviderStatus" class="layer-help"></p><label id="repairExternalLabel" hidden><input type="checkbox" id="repairExternalConsent">선택 상품 사진과 마스크의 외부 전송·유료 생성에 동의합니다. 요청 수락 뒤 중지해도 요금이 발생할 수 있습니다.</label><button type="button" class="doc-btn" id="repairPrepare">선택 물체의 보완 영역 확인</button><label>제품·재질 설명 <input id="repairHint" maxlength="300" placeholder="예: golden flaky croissant"></label><p id="repairStatus" class="layer-help" role="status" aria-live="polite"></p><img id="repairMaskPreview" alt="빨간 영역이 생성될 부분" hidden style="max-width:100%;height:180px;object-fit:contain"><button type="button" class="doc-btn" id="repairRun" hidden>이 영역만 생성</button><button type="button" class="doc-btn" id="repairCancel" hidden>생성 중지</button><img id="repairResultPreview" alt="생성 보완 후보" hidden style="max-width:100%;height:180px;object-fit:contain"><button type="button" class="doc-btn" id="repairApply" hidden>생성 보완 후보 적용</button><button type="button" class="doc-btn" id="repairRestore">생성 전 그림으로 복원</button>';
by('photoInstancesPanel').after(panel);
let openaiReady=false,powerpaintReady=false;
async function providerStatus(){try{const h=await fetch(endpoint+'/health').then(r=>r.json());openaiReady=h.openaiReady===true;powerpaintReady=h.powerpaintReady===true;}catch{openaiReady=false;powerpaintReady=false;}
 const provider=by('repairProvider').value;by('repairProviderStatus').textContent=provider==='powerpaint'?(powerpaintReady?'무료 로컬 보완을 사용할 수 있습니다. 파일 열기·리사이징 때는 자동 생성하지 않습니다. 저장된 동일 사진·영역·설명의 후보는 빠르게 불러옵니다. 처음 사진이나 새 후보 생성은 이 PC 시험에서 약 6~12분 걸렸습니다. 후보를 확인한 뒤 적용하세요.':'PowerPaint 로컬 모델이 준비되지 않았습니다. 개체분석 시작 파일을 실행하고 다시 확인하세요.'):provider==='openai'?(openaiReady?'외부 서비스 연결 준비됨. 생성 버튼을 누를 때만 전송합니다.':'외부 서비스는 아직 비활성 상태입니다. PC의 API 키와 서비스 활성화 설정이 필요합니다.'):'기존 로컬 모델은 경계·빵 형태 보완 품질이 보장되지 않는 시험 기능입니다.';
 by('repairExternalLabel').hidden=provider!=='openai';by('repairFreshLabel').hidden=provider!=='powerpaint';by('repairJoinLabel').hidden=provider!=='powerpaint';}
by('repairProvider').onchange=()=>{by('repairExternalConsent').checked=false;by('repairFresh').checked=false;providerStatus();};panel.addEventListener('toggle',()=>{if(panel.open)providerStatus();});
const say=t=>by('repairStatus').textContent=t;let prepared=null,candidate=null,busy=false,serial=0,jobId=null;
function showCandidate(){
 if(!candidate)return;const joined=by('repairJoin').checked&&candidate.joinedSrc;
 candidate.src=joined?candidate.joinedSrc:candidate.strictSrc;candidate.mask=joined?candidate.joinedMask:candidate.strictMask;candidate.method=joined?'powerpaint-v1-shape-inpainting-seam-blended':candidate.strictMethod;
 candidate.joined=!!joined;by('repairResultPreview').src=candidate.src;
 say((candidate.cached?'동일 사진의':'새')+' 보완 후보입니다. '+(joined?'접합부 주변 '+candidate.seamWidth+'px 이내의 결·명암을 함께 연결했습니다. 원본은 복원할 수 있습니다.':'원본의 보이는 픽셀 변경 0.')+' 비교 후 적용하세요.');
}
by('repairJoin').onchange=showCandidate;
async function imageData(job,file){const response=await fetch(endpoint+'/jobs/'+job+'/'+file);if(!response.ok)throw Error('보완 이미지 연결 실패');const blob=await response.blob();return new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(blob);});}
function selected(){const s=api()?.read();return s?.objects.find(o=>o.canvas)?.canvas?.getActiveObject();}
function valid(p){const s=api()?.read();return s&&s.epoch===p.state.epoch&&s.revision===p.state.revision&&s.objects.includes(p.object);}
async function cancel(){serial++;busy=false;const key=jobId;jobId=null;by('repairRun').disabled=false;by('repairCancel').hidden=true;if(key)try{await fetch(endpoint+'/jobs/'+key+'/cancel',{method:'POST'});}catch{}}
by('repairCancel').onclick=()=>{cancel();say('생성을 중지했습니다. 원본 그림은 유지됩니다.');};
by('repairPrepare').onclick=()=>{
 const state=api()?.read(),o=selected(),crop=o?.photoInstanceCrop;candidate=null;by('repairApply').hidden=true;by('repairResultPreview').hidden=true;
 if(!state||o?.photoInstanceKind!=='part'||!crop){say('사진 속 물체 자동 찾기로 나눈 그림 레이어를 선택하세요. 이전 분리 파일은 다시 분리해 주세요.');return;}
 const w=o.width,h=o.height,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(o.getElement(),0,0,w,h);const rgba=ctx.getImageData(0,0,w,h).data,points=[];
 for(let y=0;y<h;y++){let l=w,r=-1,count=0;for(let x=0;x<w;x++)if(rgba[(y*w+x)*4+3]>200){l=Math.min(l,x);r=x;count++;}if(count>=Math.max(4,Math.ceil(w*.01)))points.push([l,y],[r,y]);}
 points.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]),lower=[],upper=[];for(const p of points){while(lower.length>=2&&cross(lower.at(-2),lower.at(-1),p)<=0)lower.pop();lower.push(p);}for(const p of [...points].reverse()){while(upper.length>=2&&cross(upper.at(-2),upper.at(-1),p)<=0)upper.pop();upper.push(p);}const hull=lower.slice(0,-1).concat(upper.slice(0,-1));
 const hullCanvas=document.createElement('canvas');hullCanvas.width=w;hullCanvas.height=h;const hx=hullCanvas.getContext('2d');hx.beginPath();hull.forEach(([x,y],i)=>i?hx.lineTo(x,y):hx.moveTo(x,y));hx.closePath();hx.fill();const hullPixels=hx.getImageData(0,0,w,h).data;
 hx.clearRect(0,0,w,h);for(const other of state.objects)if(other!==o&&other.photoInstanceGroup===o.photoInstanceGroup&&other.photoInstanceKind==='part'&&other.photoInstanceCrop){const b=other.photoInstanceCrop;hx.drawImage(other.getElement(),b.x-crop.x,b.y-crop.y,b.w,b.h);}const cover=hx.getImageData(0,0,w,h).data,mask=hx.createImageData(w,h);let count=0;
 for(let i=0;i<w*h;i++){const j=i*4,fill=hullPixels[j+3]>128&&cover[j+3]>24&&rgba[j+3]===0;mask.data[j]=mask.data[j+1]=mask.data[j+2]=fill?255:0;mask.data[j+3]=255;if(fill)count++;}
 if(!count||count>w*h*.3){say('확실한 가림 영역을 찾지 못했습니다. 원본 그림을 유지합니다.');canvas.width=canvas.height=hullCanvas.width=hullCanvas.height=0;return;}
 hx.putImageData(mask,0,0);const maskSrc=hullCanvas.toDataURL('image/png'),source=canvas.toDataURL('image/png');const overlay=ctx.getImageData(0,0,w,h);for(let i=0;i<w*h;i++)if(mask.data[i*4]){overlay.data[i*4]=255;overlay.data[i*4+1]=40;overlay.data[i*4+2]=60;overlay.data[i*4+3]=180;}ctx.putImageData(overlay,0,0);by('repairMaskPreview').src=canvas.toDataURL('image/png');by('repairMaskPreview').hidden=false;by('repairRun').hidden=false;
 prepared={state,object:o,source,mask:maskSrc,count};if(!by('repairHint').value)by('repairHint').value=state.objects.filter(x=>typeof x.text==='string').sort((a,b)=>(b.fontSize||0)-(a.fontSize||0))[0]?.text.slice(0,100)||'same original product';say(count.toLocaleString()+'픽셀의 빨간 영역만 추정 생성합니다. 영역과 설명을 확인한 뒤 실행하세요.');canvas.width=canvas.height=hullCanvas.width=hullCanvas.height=0;
};
by('repairRun').onclick=async()=>{
 const provider=by('repairProvider').value,fresh=provider==='powerpaint'&&by('repairFresh').checked,externalConsent=by('repairExternalConsent').checked;if(provider==='powerpaint'&&!powerpaintReady){say('PowerPaint 로컬 모델 준비 상태를 먼저 확인하세요.');return;}if(provider==='openai'&&(!openaiReady||!externalConsent)){say('외부 서비스 설정과 이번 전송 동의를 먼저 확인하세요.');return;}const p=prepared;if(busy||!p||!valid(p)||selected()!==p.object){say('대상이 바뀌었습니다. 보완 영역을 다시 확인하세요.');return;}by('repairExternalConsent').checked=false;by('repairFresh').checked=false;const token=++serial;busy=true;by('repairRun').disabled=true;by('repairCancel').hidden=false;by('repairApply').hidden=true;say(provider==='openai'?'선택 상품과 마스크만 외부 서비스로 전송합니다.':'로컬 생성 준비 · CPU에서 수 분 걸릴 수 있습니다.');
 try{const response=await fetch(endpoint+'/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,fresh,externalConsent,source:p.source,mask:p.mask,hint:by('repairHint').value,matte:'#5f4b3d'})});const job=await response.json();if(!response.ok)throw Error(job.error);if(token!==serial){await fetch(endpoint+'/jobs/'+job.id+'/cancel',{method:'POST'});return;}jobId=job.id;
  while(token===serial){await new Promise(resolve=>setTimeout(resolve,1200));if(!valid(p)){await cancel();say('원본이 바뀌어 생성을 취소했습니다.');return;}const result=await fetch(endpoint+'/jobs/'+job.id).then(r=>r.json());say((result.phase||'로컬 생성 중')+(result.progress!==undefined?' · '+result.progress+'%':''));if(result.status==='failed')throw Error(result.error);if(result.status==='cancelled')return;if(result.status!=='completed')continue;
   if(result.result.protectedRgbChanged!==0)throw Error('보호할 원본 픽셀 검증을 통과하지 못했습니다.');const src=await imageData(job.id,result.result.image);let actualMask=p.mask;if(result.result.mask)actualMask=await imageData(job.id,result.result.mask);
   let joinedSrc=null,joinedMask=null;if(result.result.seamImage&&result.result.seamMask){joinedSrc=await imageData(job.id,result.result.seamImage);joinedMask=await imageData(job.id,result.result.seamMask);}if(token!==serial||!valid(p))return;
   candidate={...p,strictSrc:src,strictMask:actualMask,strictMethod:result.result.method,joinedSrc,joinedMask,seamWidth:result.result.seamWidth,cached:result.result.cached};by('repairResultPreview').hidden=false;by('repairApply').hidden=false;showCandidate();break;}
 }catch(e){say('생성 확인 필요: '+e.message+' 원본은 유지했습니다.');}finally{if(token===serial){busy=false;by('repairRun').disabled=false;by('repairCancel').hidden=true;jobId=null;}}
};
by('repairApply').onclick=async()=>{const p=candidate;if(!p||!valid(p)||selected()!==p.object){say('대상이 바뀌었습니다. 다시 확인하세요.');return;}const image=new Image();image.src=p.src;await image.decode();if(!valid(p))return;const o=p.object;o.generatedPhotoSource=o.generatedPhotoSource||o.getSrc();o.generatedRegionMask=p.mask;o.generatedMethod=p.method||'local-masked-inpainting';o.setElement(image);if(!o.layerName.includes('생성 보완'))o.layerName+=' · 생성 보완';api().commit(p.state.width,p.state.height,{epoch:p.state.epoch,revision:p.state.revision,apply:true});by('repairApply').hidden=true;candidate=null;prepared=null;say('선택 그림에 보완을 적용했습니다. '+(p.joined?'접합부 주변 색·질감도 보정했습니다. ':'원본 보이는 부분은 유지했습니다. ')+'생성 전 그림으로 복원할 수 있습니다.');};
by('repairRestore').onclick=async()=>{const s=api()?.read(),o=selected();if(!s||!/^data:image\/png;base64,/.test(o?.generatedPhotoSource||'')){say('생성 보완된 그림을 선택하세요.');return;}const im=new Image();im.src=o.generatedPhotoSource;await im.decode();if(api().read().epoch!==s.epoch||api().read().revision!==s.revision)return;o.setElement(im);delete o.generatedPhotoSource;delete o.generatedRegionMask;delete o.generatedMethod;o.layerName=o.layerName.replace(' · 생성 보완','');api().commit(s.width,s.height,{epoch:s.epoch,revision:s.revision,apply:true});say('생성 전 그림으로 복원했습니다.');};
for(const event of ['coex:layer-source','coex:layer-edit'])window.addEventListener(event,()=>{if(busy)cancel();});
window.addEventListener('coex:layer-source',()=>{prepared=null;candidate=null;by('repairFresh').checked=false;by('repairExternalConsent').checked=false;by('repairRun').hidden=true;by('repairApply').hidden=true;by('repairMaskPreview').hidden=true;by('repairResultPreview').hidden=true;by('repairHint').value='';});
